import type { EarningPaymentStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface PaymentStatusEntry {
  label: string;
  variant: BadgeVariants;
}

// Key order defines the user-visible filter order (taken from the former earningsStatuses select list).
// `transaction_processing` was missing from that hand-written list; deriving the list below restores it (intended).
export const paymentStatusBadge: Record<EarningPaymentStatus, PaymentStatusEntry> = {
  pending: { label: 'Pending', variant: 'default' },
  under_review: { label: 'Under Review', variant: 'default' },
  ready_for_payment: { label: 'Ready for Payment', variant: 'info' },
  transaction_processing: { label: 'Transaction Processing', variant: 'default' },
  completed: { label: 'Completed', variant: 'success' },
  manually_completed: { label: 'Manually Completed', variant: 'success' },
  rejected: { label: 'Rejected', variant: 'destructive' },
  failed: { label: 'Failed', variant: 'destructive' },
};

const defaultPaymentStatus: PaymentStatusEntry = { label: '', variant: 'default' };

export function getPaymentStatusBadge(status: EarningPaymentStatus): PaymentStatusEntry {
  return paymentStatusBadge[status] ?? { ...defaultPaymentStatus, label: snakeCaseToCapitalizedCase(status) };
}

export const earningsStatuses: SelectItem<EarningPaymentStatus>[] = Object.entries(paymentStatusBadge).map(
  ([value, { label }]) => ({ value: value as EarningPaymentStatus, name: label })
);
